use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Role {
    Knight,
    Knave,
    Spy,
}

impl fmt::Display for Role {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let s = match self {
            Role::Knight => "Knight",
            Role::Knave => "Knave",
            Role::Spy => "Spy",
        };
        write!(f, "{}", s)
    }
}

/// Check whether a person's statement is consistent with their role.
/// - Knight: statement must be true
/// - Knave: statement must be false
/// - Spy: anything goes
fn consistent(role: Role, statement_truth: bool) -> bool {
    match role {
        Role::Knight => statement_truth,
        Role::Knave => !statement_truth,
        Role::Spy => true,
    }
}

fn main() {
    let roles = [Role::Knight, Role::Knave, Role::Spy];
    let mut solutions = 0;

    // Try every permutation of (Alice, Bob, Charlie) -> (role, role, role)
    for &alice in &roles {
        for &bob in &roles {
            for &charlie in &roles {
                // Each role must be assigned exactly once
                if alice == bob || bob == charlie || alice == charlie {
                    continue;
                }

                // Statement truth values given the assignment:
                let alice_says   = charlie == Role::Knave;   // "Charlie is a knave"
                let bob_says     = alice == Role::Knight;    // "Alice is a knight"
                let charlie_says = charlie == Role::Spy;     // "I am the spy"

                if consistent(alice, alice_says)
                    && consistent(bob, bob_says)
                    && consistent(charlie, charlie_says)
                {
                    println!(
                        "Valid assignment -> Alice: {}, Bob: {}, Charlie: {}",
                        alice, bob, charlie
                    );
                    solutions += 1;
                }
            }
        }
    }

    println!("\nTotal valid assignments: {}", solutions);
}
```

